        for x3 in np.linspace(x2,1,51):
            if x1==x2 or x2==x3 or x1==x3: continue
            for s1 in [1,-1]:
                for s2 in [1,-1]:
                    for s3 in [1,-1]:
                        # Solve linear system for a,b,c
                        A=np.array([[x1**2,x1,1],[x2**2,x2,1],[x3**2,x3,1]],float)
                        y=np.array([s1,s2,s3],float)
                        try:
                            coeff=np.linalg.solve(A,y)
                        except np.linalg.LinAlgError:
                            continue
                        a,b,c=coeff
                        # Check constraint
                        xs=np.linspace(0,1,201)
                        if np.all(np.abs(a*xs**2+b*xs+c)<=1+1e-6):
                            L=abs(a)+abs(b)+abs(c)
                            if L>maxL:
                                maxL=L
                                best=(x1,x2,x3,s1,s2,s3,a,b,c)
