import itertools
from functools import lru_cache
import sympy

# Allowed substrings that can be removed
removals = {"123", "231", "312"}

@lru_cache(maxsize=None)
def reducible(t):
    """Return True if string t can be reduced to empty by removing allowed substrings."""
    n = len(t)
    if n == 0:
        return True
    # Try every possible removal of a valid 3‑character substring
    for i in range(n - 2):
        if t[i:i+3] in removals:
            if reducible(t[:i] + t[i+3:]):
                return True
    return False

count = 0

# Generate all strings of length 15 with exactly five 1's, five 2's, and five 3's
positions = range(15)
for ones in itertools.combinations(positions, 5):
    remaining1 = set(positions) - set(ones)
    for twos in itertools.combinations(remaining1, 5):
        threes = tuple(sorted(remaining1 - set(twos)))
        # Build the string
        s = [''] * 15
        for pos in ones:
            s[pos] = '1'
        for pos in twos:
            s[pos] = '2'
        for pos in threes:
            s[pos] = '3'
        s = ''.join(s)
        # Condition 1: no two adjacent characters are the same
        if any(s[i] == s[i+1] for i in range(14)):
            continue
        # Condition 2: reducible to empty
        if reducible(s):
            count += 1

# Output the result in the required format
answer = sympy.Integer(count)
print(f"ANSWER: {sympy.latex(answer)}")
