import sys
from itertools import combinations
from functools import lru_cache
import sympy

# Patterns that can be removed
PATTERNS = {'123', '231', '312'}

@lru_cache(maxsize=None)
def reducible(s: str) -> bool:
    """Return True if string s can be fully reduced by removing patterns."""
    n = len(s)
    if n == 0:
        return True
    if n % 3 != 0:
        return False
    # try all possible removals
    for i in range(n - 2):
        if s[i:i+3] in PATTERNS:
            new_s = s[:i] + s[i+3:]
            if reducible(new_s):
                return True
    return False

def main():
    positions = list(range(15))
    count = 0

    # iterate over all unique permutations of 5 1's, 5 2's, 5 3's
    for comb1 in combinations(positions, 5):
        remaining1 = set(positions) - set(comb1)
        for comb2 in combinations(remaining1, 5):
            comb3 = tuple(sorted(remaining1 - set(comb2)))
            # build string
            s = [''] * 15
            for i in comb1:
                s[i] = '1'
            for i in comb2:
                s[i] = '2'
            for i in comb3:
                s[i] = '3'
            string = ''.join(s)
            # condition 1: no adjacent equal
            if any(string[i] == string[i+1] for i in range(14)):
                continue
            # condition 2: reducible
            if reducible(string):
                count += 1

    print(f"ANSWER: {sympy.latex(sympy.Integer(count))}")

if __name__ == "__main__":
    main()
