import itertools

def solve():
    """
    Problem:
    4x4 grid.
    - No two coins orthogonally adjacent.
    - Each 2x2 square has at least one coin.
    """
    count = 0
    # There are 2^16 = 65536 possible placements.
    for mask in range(1 << 16):
        # Represent the mask as a 4x4 grid
        grid = [[0]*4 for _ in range(4)]
        for r in range(4):
            for c in range(4):
                if (mask >> (r * 4 + c)) & 1:
                    grid[r][c] = 1

        # Condition 1: No two coins are orthogonally adjacent
        is_independent_set = True
        for r in range(4):
            for c in range(4):
                if grid[r][c] == 1:
                    # Check right
                    if c + 1 < 4 and grid[r][c+1] == 1:
                        is_independent_set = False
                        break
                    # Check down
                    if r + 1 < 4 and grid[r+1][c] == 1:
                        is_independent_set = False
                        break
            if not is_independent_set:
                break

        if not is_independent_set:
            continue

        # Condition 2: Each 2x2 square has at least one coin
        all_2x2_filled = True
        for r in range(3):
            for c in range(3):
                # Sum of coins in the 2x2 square starting at (r, c)
                sum_2x2 = grid[r][c] + grid[r+1][c] + grid[r][c+1] + grid[r+1][c+1]
                if sum_2x2 == 0:
                    all_2x2_filled = False
                    break
            if not all_2x2_filled:
                break

        if all_2x2_filled:
            count += 1

    return count

if __name__ == "__main__":
    result = solve()
    print(f"ANSWER: {result}")
