import sympy as sp

def rank_of_vectors(vectors, n):
    """Return rank over GF(2) of list of integer bitmasks of length n."""
    pivots = {}      # map pivot position -> basis vector
    rank = 0
    for v in vectors:
        x = v
        # reduce x by existing pivots
        for i in range(n-1, -1, -1):
            if (x >> i) & 1:
                if i in pivots:
                    x ^= pivots[i]   # eliminate pivot bit
                else:
                    pivots[i] = x
                    rank += 1
                    break
    return rank

def all_vectors_of_weight(n, k):
    """Generate all bitmasks of length n with exactly k ones."""
    from itertools import combinations
    for comb in combinations(range(n), k):
        mask = 0
        for i in comb:
            mask |= 1 << i
        yield mask

def compute_sum(max_n=10):
    total = 0
    for n in range(1, max_n+1):
        for k in range(1, n+1):
            vectors = list(all_vectors_of_weight(n, k))
            r = rank_of_vectors(vectors, n)
            components = 2 ** (n - r)
            total += components
    return total

if __name__ == "__main__":
    total = compute_sum(10)
    print(f"ANSWER: {sp.latex(total)}")
